-- Blog: dois artigos de decoração para arquitetos e designers de interiores.
insert into public.ara_posts (slug,titulo,subtitulo,resumo,conteudo,ilustracao,foto_url,publicado,data,ordem,seo_titulo,seo_descricao) values ('tendencias-decoracao-2026-cristais','Cor do ano 2026 e CASACOR: os cristais que combinam com as tendências de decoração','Cloud Dancer, o tema Mente e Coração e as pedras que conversam com a casa de 2026.','A cor do ano da Pantone e o tema da CASACOR 2026 apontam para casas mais calmas e naturais. Veja quais cristais combinam com essas tendências.','<p>Duas referências guiam a decoração em 2026: a cor do ano da Pantone e o tema da CASACOR, uma das maiores mostras de arquitetura e interiores do Brasil. As duas apontam na mesma direção: casas mais calmas, com materiais naturais e espaço para pausa. É um cenário em que os cristais entram com naturalidade.</p>
<h2>Cloud Dancer, a cor do ano de 2026</h2>
<p>A Pantone escolheu o <strong>Cloud Dancer (PANTONE 11-4201)</strong>, um branco suave, quase off-white, como cor de 2026. Foi a primeira vez que um tom de branco recebeu o título. Segundo o Pantone Color Institute, a cor transmite simplicidade, leveza e foco, como uma tela em branco.</p>
<p>Na decoração, um fundo tão neutro pede objetos com textura e brilho para não ficar frio. É aí que as pedras naturais ajudam.</p>
<h2>Os cristais que combinam com o Cloud Dancer</h2>
<h3>Selenita: branco sobre branco</h3>
<p>A selenita tem um brilho sedoso, quase perolado. Em ambientes off-white, cria uma composição tom sobre tom, sofisticada e serena. Na tradição, é a pedra da limpeza energética. Veja a <a href="/loja/aura-da-limpeza">Aura da Limpeza</a>.</p>
<h3>Quartzo transparente: luz e clareza</h3>
<p>O cristal de quartzo pega a luz do ambiente e a devolve. Perto de uma janela, sobre um móvel claro, é a escolha mais coerente com a ideia de clareza da cor do ano. Veja a <a href="/loja/aura-da-clareza">Aura da Clareza</a>.</p>
<h3>Pirita: o dourado que aquece</h3>
<p>Brancos muito limpos ganham calor com metais. O brilho dourado da pirita faz esse papel de forma natural, e combina com latão, palha e madeira. Na tradição, é a pedra da prosperidade. Veja a <a href="/loja/aura-da-prosperidade">Aura da Prosperidade</a>.</p>
<h3>Ametista: o contraste de cor</h3>
<p>Para quem quer um ponto de cor sem fugir da calma, o violeta da ametista se destaca sobre o off-white sem pesar. É ligada à tranquilidade e ao sono. Veja a <a href="/loja/aura-da-calma">Aura da Calma</a>.</p>
<h3>Lápis-lazúli e sodalita: o azul profundo</h3>
<p>Os azuis profundos dessas pedras trazem contraste e combinam com detalhes em dourado. Funcionam bem em escritórios e bibliotecas.</p>
<h2>CASACOR 2026: Mente e Coração</h2>
<p>O tema da CASACOR 2026 é <strong>Mente e Coração</strong>. A proposta trata a casa como refúgio: um espaço de acolhimento, pausa e reconexão, em resposta ao excesso de informação do dia a dia. Os ambientes valorizam natureza, bem-estar, afeto e experiências sensoriais.</p>
<p>Cristais naturais conversam diretamente com essa ideia. São matéria-prima da natureza, formada ao longo de milhões de anos, e carregam significado para quem os escolhe. Uma pedra na mesa de cabeceira ou uma composição no hall de entrada é um jeito simples de levar o tema para casa.</p>
<h2>Como usar na prática</h2>
<ul>
<li><strong>Agrupe em vez de espalhar:</strong> três pedras juntas sobre uma bandeja têm mais presença do que várias soltas pela casa.</li>
<li><strong>Use a luz natural:</strong> perto de janelas, cristais transparentes e o dourado da pirita ganham vida.</li>
<li><strong>Crie um ponto focal:</strong> uma caixa com mosaico de cristais, como a <a href="/arca#colecao">Arca da ARA</a>, organiza as pedras e vira peça de destaque na mesa de centro ou no aparador. Veja ideias de <a href="arca-de-cristais-na-decoracao.html">onde colocar a Arca</a>.</li>
</ul>
<p class="muted">Fontes: <a href="https://www.cnnbrasil.com.br/lifestyle/pantone-escolhe-a-cor-do-ano-de-2026-veja-qual/" target="_blank" rel="noopener">CNN Brasil</a>, <a href="https://diariodocomercio.com.br/variedades/casacor-2026-vai-trazer-tema-mente-coracao/" target="_blank" rel="noopener">Diário do Comércio</a>.</p>','quartzo','',true,'2026-10-08',-2,'Cor do ano 2026 e CASACOR: cristais na decoração | ARA','Cloud Dancer, a cor do ano 2026 da Pantone, e o tema Mente e Coração da CASACOR: veja quais cristais combinam com as tendências de decoração.') on conflict (slug) do update set titulo=excluded.titulo, subtitulo=excluded.subtitulo, resumo=excluded.resumo, conteudo=excluded.conteudo, ilustracao=excluded.ilustracao, foto_url=excluded.foto_url, publicado=excluded.publicado, data=excluded.data, ordem=excluded.ordem, seo_titulo=excluded.seo_titulo, seo_descricao=excluded.seo_descricao, atualizado_em=now();
insert into public.ara_posts (slug,titulo,subtitulo,resumo,conteudo,ilustracao,foto_url,publicado,data,ordem,seo_titulo,seo_descricao) values ('arca-de-cristais-na-decoracao','Cristais na decoração: onde colocar a Arca na sala, no hall e no escritório','Ideias para expor cristais naturais em projetos de interiores, com dicas para arquitetos e designers.','Mesa de centro, aparador do hall ou escritório perto da janela: como usar a Arca, a caixa de cristais da ARA, na decoração.','<p>Cristais naturais deixaram de ficar escondidos na gaveta. Em projetos de interiores, eles entram como objeto de decoração: trazem textura, cor e um pedaço da natureza para dentro de casa. O desafio é expor as pedras sem que elas pareçam soltas ou bagunçadas.</p>
<p>A Arca da ARA nasceu para isso. É uma caixa de madeira e vidro com um mosaico de cristais naturais brasileiros montado à mão. As pedras ficam organizadas, protegidas da poeira e visíveis de todos os lados, como uma pequena vitrine. Abaixo, três lugares onde ela funciona bem.</p>
<h2>Na mesa de centro da sala</h2>
<p>É o lugar mais clássico. Sobre um tampo de pedra, madeira ou laca clara, a Arca vira o ponto de atenção da sala e puxa conversa com quem chega. Combine com um livro de arte e uma planta para compor a mesa em três alturas diferentes.</p>
<p><strong>Dica:</strong> em mesas claras, como as de travertino ou mármore, a madeira da caixa aquece o conjunto. Em mesas escuras, prefira pedras claras dentro da Arca, como o quartzo transparente e a selenita.</p>
<h2>No aparador do hall de entrada</h2>
<p>O hall é a primeira impressão da casa, e na tradição dos cristais é também o lugar das pedras de proteção, como a turmalina negra. Um aparador com espelho, uma luminária de mesa e a Arca formam uma composição completa, que recebe quem entra.</p>
<p><strong>Dica:</strong> posicione a Arca de lado para o espelho. O vidro e o reflexo multiplicam o brilho das pedras.</p>
<h2>Na mesa do escritório, perto da janela</h2>
<p>A luz natural atravessa o vidro e acende os cristais ao longo do dia. No escritório, a Arca tira o ambiente do lugar-comum e traz as pedras ligadas ao foco e à prosperidade, como a pirita e a fluorita verde.</p>
<p><strong>Dica:</strong> evite sol direto por muitas horas em pedras sensíveis, como a ametista, que pode desbotar. Luz filtrada por uma cortina leve é o ideal.</p>
<h2>Uma peça única para cada casa</h2>
<p>Cada Arca é montada a partir do nome completo e da data de nascimento de quem vai recebê-la. Por isso nenhuma é igual a outra. Existem três modelos: a <strong>Essencial</strong> (30 × 16 × 8,5 cm), a <strong>Plena</strong> (36 × 21 × 12 cm) e a <strong>Ateliê</strong>, com caixa feita sob encomenda por um marceneiro artesão, em madeira maciça. <a href="/arca#colecao">Veja os modelos da Arca</a>.</p>
<h2 id="profissionais">Para arquitetos e designers de interiores</h2>
<p>Se você está assinando um projeto, a Arca pode ser pensada junto com ele:</p>
<ul>
<li><strong>Pedras na paleta do ambiente:</strong> escolhemos os cristais para conversar com as cores, os tecidos e os materiais do projeto.</li>
<li><strong>Medidas e madeira sob encomenda:</strong> na Arca Ateliê, a caixa é feita à mão para o espaço onde vai ficar.</li>
<li><strong>Presente de entrega de obra:</strong> uma peça única, com o nome do cliente, para fechar o projeto.</li>
<li><strong>Condição especial para profissionais.</strong></li>
</ul>
<p><a href="https://wa.me/5511973371416?text=Ol%C3%A1!%20Sou%20arquiteto(a)%20%2F%20designer%20de%20interiores%20e%20quero%20saber%20da%20condi%C3%A7%C3%A3o%20para%20projetos." target="_blank" rel="noopener">Fale com a ARA pelo WhatsApp</a> e conte sobre o seu projeto.</p>','pirita','/img/arca-cristais-na-sala.56dbbf25.jpg',true,'2026-10-08',-1,'Cristais na decoração: sala, hall e escritório | ARA','Como usar cristais naturais na decoração: a Arca da ARA na mesa de centro, no aparador do hall e no escritório. Para arquitetos e designers de interiores.') on conflict (slug) do update set titulo=excluded.titulo, subtitulo=excluded.subtitulo, resumo=excluded.resumo, conteudo=excluded.conteudo, ilustracao=excluded.ilustracao, foto_url=excluded.foto_url, publicado=excluded.publicado, data=excluded.data, ordem=excluded.ordem, seo_titulo=excluded.seo_titulo, seo_descricao=excluded.seo_descricao, atualizado_em=now();
